mapper.select:
SELECT NOTICE_IDX AS noticeIdx, TITLE AS title, VIEWS AS views, IS_FIXED AS isFixed, CREATED_AT AS createdAt FROM NOTICE WHERE IS_FIXED = 'N'
AND (TITLE LIKE CONCAT('%', #{keyword}, '%') OR CONTENTS LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY CREATED_AT DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE NOTICE
SET VIEWS = VIEWS + 1
WHERE NOTICE_IDX = #{noticeIdx}

UPDATE NOTICE
SET TITLE    = #{title},
    CONTENTS = #{contents},
    IS_FIXED = #{isFixed}
WHERE NOTICE_IDX = #{noticeIdx}
